func NewManagement(cfg Config) (*Management, error) {
	if cfg.Token != "" && (len(cfg.Token) < 32 || strings.ContainsFunc(cfg.Token, invalidTokenRune)) {
		return nil, errors.New("terrabase: Token must be empty or the management service credential: at least 32 characters without whitespace")
	}
	c, err := newClient(cfg)
	if err != nil {
		return nil, err
	}
	return &Management{c: c}, nil
}

func invalidTokenRune(r rune) bool { return unicode.IsSpace(r) || unicode.IsControl(r) }

// WithToken returns a view that acts as the user of a ts-auth access token.
// TerraBase accepts it on the client listener only.
func (m *Management) WithToken(accessToken string) *ManagementUser {
	u := &ManagementUser{c: m.c, token: accessToken}
	if accessToken == "" || strings.ContainsFunc(accessToken, invalidTokenRune) {
		u.err = errors.New("terrabase: WithToken needs a ts-auth access token without whitespace")
	}
	return u
}

// As returns a view that acts as the ts-auth user userID with the management
// service credential (Config.Token), sending X-TerraBase-User-Id on every
// request. TerraBase accepts the credential only on its loopback admin
// listener and trusts the user id because the credential authenticated the
// caller: never take it from browser input.
func (m *Management) As(userID string) *ManagementUser {
	u := &ManagementUser{c: m.c, header: http.Header{"X-Terrabase-User-Id": {userID}}}
	if err := checkID(userID); err != nil {
		u.err = fmt.Errorf("terrabase: user ID: %w", err)
	}
	if m.c.token == "" {
		u.err = errors.Join(u.err, errors.New("terrabase: As needs Config.Token, the management service credential"))
	}
	return u
}

func (o PageOptions) query() url.Values {
	q := url.Values{}
	if o.Limit > 0 {
		q.Set("limit", strconv.Itoa(o.Limit))
	}
	if o.After != "" {
		q.Set("after", o.After)
	}
	return q
}

// call sends one Management request as the user.
func (u *ManagementUser) call(ctx context.Context, method string, path []string, query url.Values, in, out any) error {
	if u.err != nil {
		return u.err
	}
	if err := entityid.Path(path); err != nil {
		return fmt.Errorf("terrabase: %s management request path: %w", method, err)
	}
	var body []byte
	if in != nil {
		var err error
		body, err = json.Marshal(in)
		if err != nil {
			return fmt.Errorf("terrabase: encode %s management request: %w", method, err)
		}
		if err := entityid.Body(body); err != nil {
			return fmt.Errorf("terrabase: %s management request body: %w", method, err)
		}
		if err := entityid.Model(in); err != nil {
			return fmt.Errorf("terrabase: %s management request model: %w", method, err)
		}
	}
	req := request{
		method:     method,
		body:       body,
		path:       append([]string{"v1", "management"}, path...),
		query:      query,
		header:     u.header,
		token:      u.token,
		replaySafe: method == http.MethodGet,
	}
	_, err := u.c.call(ctx, req, nil, out)
	return err
}

func orgPath(org string, extra ...string) []string {
	return append([]string{"organizations", org}, extra...)
}

func projectPath(org, project string, extra ...string) []string {
	return orgPath(org, append([]string{"projects", project}, extra...)...)
}

func databasePath(org, project, databaseID string, extra ...string) []string {
	return projectPath(org, project, append([]string{"databases", databaseID}, extra...)...)
}

func get[T any](ctx context.Context, u *ManagementUser, path []string, query url.Values) (*T, error) {
	var out T
	if err := u.call(ctx, http.MethodGet, path, query, nil, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

func (u *ManagementUser) Projects(ctx context.Context, org string, opts PageOptions) (*Page[Project], error) {
	return get[Page[Project]](ctx, u, orgPath(org, "projects"), opts.query())
}

func (u *ManagementUser) DeleteProject(ctx context.Context, org, project string) error {
	return u.call(ctx, http.MethodDelete, projectPath(org, project), nil, nil, nil)
}

func (u *ManagementUser) Databases(ctx context.Context, org, project string, opts PageOptions) (*Page[ManagedDatabase], error) {
	return get[Page[ManagedDatabase]](ctx, u, projectPath(org, project, "databases"), opts.query())
}

func (u *ManagementUser) DeleteDatabase(ctx context.Context, org, project, databaseID string) error {
	return u.call(ctx, http.MethodDelete, databasePath(org, project, databaseID), nil, nil, nil)
}

func (u *ManagementUser) ProjectAPIKeys(ctx context.Context, org, project string, opts PageOptions) (*Page[ProjectAPIKey], error) {
	return get[Page[ProjectAPIKey]](ctx, u, projectPath(org, project, "api-keys"), opts.query())
}

// RevokeProjectAPIKey revokes a project's data API key; it stops
// authenticating immediately. A viewer cannot.
func (u *ManagementUser) RevokeProjectAPIKey(ctx context.Context, org, project, key string) error {
	return u.call(ctx, http.MethodDelete, projectPath(org, project, "api-keys", key), nil, nil, nil)
}

func newClient(cfg Config) (*Client, error) {
	if cfg.Resolver != nil && cfg.BaseURL != "" {
		return nil, errors.New("terrabase: set either Resolver or BaseURL")
	}
	if cfg.Resolver == nil {
		if _, err := parseBaseURL(cfg.BaseURL); err != nil {
			return nil, err
		}
		cfg.Resolver = StaticResolver(cfg.BaseURL)
	}
	hc := &http.Client{Transport: &http.Transport{
		Proxy:             http.ProxyFromEnvironment,
		TLSClientConfig:   &tls.Config{MinVersion: tls.VersionTLS13},
		ForceAttemptHTTP2: true,
		IdleConnTimeout:   90 * time.Second,
	}}
	if cfg.HTTPClient != nil {
		copied := *cfg.HTTPClient
		hc = &copied
	}
	hc.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	c := &Client{resolver: cfg.Resolver, token: cfg.Token, hc: hc, maxRetries: cfg.MaxRetries, maxResponse: cfg.MaxResponseBytes}
	switch {
	case c.maxRetries == 0:
		c.maxRetries = DefaultMaxRetries
	case c.maxRetries < 0:
		c.maxRetries = 0
	}
	if c.maxResponse <= 0 {
		c.maxResponse = DefaultMaxResponseBytes
	}
	return c, nil
}

func (c *Client) url(ctx context.Context, segments []string, query url.Values) (string, error) {
	for _, s := range segments {
		if s == "" || s == "." || s == ".." || strings.Contains(s, "/") {
			return "", fmt.Errorf("terrabase: path segment %q is empty, a dot segment or contains a slash", s)
		}
	}
	raw, err := c.resolver.Resolve(ctx)
	if err != nil {
		return "", fmt.Errorf("terrabase: resolve endpoint: %w", err)
	}
	base, err := parseBaseURL(raw)
	if err != nil {
		return "", err
	}
	u := *base
	u.RawPath = u.EscapedPath()
	for _, s := range segments {
		u.Path += "/" + s
		u.RawPath += "/" + url.PathEscape(s)
	}
	u.RawQuery = query.Encode()
	return u.String(), nil
}

// do sends req with the client's retry policy and returns a 2xx response or

func (c *Client) do(ctx context.Context, req request) (*response, error) {
	if len(req.body) > MaxRequestBytes {
		return nil, fmt.Errorf("terrabase: request body is %d bytes, over the %d byte limit", len(req.body), MaxRequestBytes)
	}
	target, err := c.url(ctx, req.path, req.query)
	if err != nil {
		return nil, err
	}
	readOnly := req.method == http.MethodGet || req.readOnly
	for attempt := 0; ; attempt++ {
		resp, err := c.send(ctx, req, target)
		if err != nil {
			if !readOnly {
				return nil, fmt.Errorf("%w: %w", ErrCommitUncertain, err)
			}
			if ctx.Err() != nil || !req.replaySafe || attempt >= c.maxRetries {
				return nil, err
			}
			if err := sleep(ctx, backoff(attempt)); err != nil {
				return nil, err
			}
			continue
		}
		if resp.status >= 200 && resp.status < 300 {
			return resp, nil
		}
		apiErr := parseAPIError(resp.status, resp.header, resp.body)
		if !readOnly && apiErr.Code == ErrCommitUncertain {
			return resp, apiErr
		}
		if delay, ok := retryDelay(apiErr, attempt, req.replaySafe); ok && attempt < c.maxRetries {
			if err := sleep(ctx, delay); err != nil {
				return nil, err
			}
			continue
		}
		return resp, apiErr
	}
}

func (c *Client) send(ctx context.Context, req request, target string) (*response, error) {
	method := req.method
	var rd io.Reader
	if req.body != nil {
		rd = bytes.NewReader(req.body)
	}
	hr, err := http.NewRequestWithContext(ctx, method, target, rd)
	if err != nil {
		return nil, fmt.Errorf("terrabase: build request: %w", err)
	}
	for k, v := range req.header {
		hr.Header[k] = v
	}
	hr.Header.Set("Authorization", "Bearer "+cmp.Or(req.token, c.token))
	hr.Header.Set("Accept", "application/json")
	if req.body != nil {
		hr.Header.Set("Content-Type", cmp.Or(req.contentType, "application/json"))
	}
	res, err := c.hc.Do(hr)
	if err != nil {
		return nil, fmt.Errorf("terrabase: %s %s: %w", method, hr.URL.Path, err)
	}
	defer res.Body.Close()
	data, err := io.ReadAll(io.LimitReader(res.Body, c.maxResponse+1))
	if err != nil {
		return nil, fmt.Errorf("terrabase: read %s %s response: %w", method, hr.URL.Path, err)
	}
	if int64(len(data)) > c.maxResponse {
		return nil, fmt.Errorf("terrabase: %s %s response exceeds %d bytes", method, hr.URL.Path, c.maxResponse)
	}
	return &response{status: res.StatusCode, header: res.Header, body: data}, nil
}

func (c *Client) call(ctx context.Context, req request, in, out any) (*response, error) {
	if in != nil {
		body, err := json.Marshal(in)
		if err != nil {
			return nil, fmt.Errorf("terrabase: encode request: %w", err)
		}
		req.body = body
	}
	resp, err := c.do(ctx, req)
	if err != nil {
		return resp, err
	}
	if out != nil && !(resp.status == http.StatusNoContent && len(bytes.TrimSpace(resp.body)) == 0) {
		if err := decodeExact(resp.body, out); err != nil {
			return resp, fmt.Errorf("terrabase: decode %s response: %w", req.method, err)
		}
		if err := entityid.Model(out); err != nil {
			return resp, fmt.Errorf("terrabase: invalid response: %w", err)
		}
	}
	return resp, nil
}

// decodeExact decodes JSON with UseNumber so numbers stay exact.
func decodeExact(data []byte, v any) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	if err := dec.Decode(v); err != nil {
		return err
	}
	if dec.More() {
		return errors.New("trailing data after JSON value")
	}
	return nil
}

