func Generate(directory string, cfg Config, now time.Time) (Record, error) {
	if err := cfg.validate(); err != nil || !filepath.IsAbs(directory) || now.IsZero() || secureParents(directory) != nil {
		return Record{}, ErrMaterial
	}
	if _, err := os.Lstat(directory); err == nil {
		record, loadErr := Load(directory)
		if loadErr != nil || !sameConfig(record.Config, cfg) {
			return Record{}, ErrMaterial
		}
		return record, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return Record{}, ErrMaterial
	}
	if err := os.Mkdir(directory, 0o700); err != nil {
		return Record{}, fmt.Errorf("create private material directory: %w", err)
	}
	files, public, err := build(cfg, now.UTC())
	if err != nil {
		return Record{}, err
	}
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	record := Record{SchemaVersion: 1, Config: cfg, IssuedAt: now.UTC(),
		ExpiresAt: now.UTC().Add(time.Duration(cfg.ValidityHours) * time.Hour), Public: public}
	for name, body := range files {
		purpose, slot := classify(name)
		if purpose == "" || len(body) == 0 || len(body) > int(bootstrap.MaxSecretBytes) {
			return Record{}, ErrMaterial
		}
		record.Files = append(record.Files, File{Name: name, Purpose: purpose, Slot: slot,
			SHA256: digest(body), MaxBytes: int64(len(body))})
	}
	slices.SortFunc(record.Files, func(a, b File) int { return strings.Compare(a.Name, b.Name) })
	for _, file := range record.Files {
		if err := writeOnce(filepath.Join(directory, file.Name), files[file.Name]); err != nil {
			return Record{}, fmt.Errorf("write private material %s: %w", file.Name, err)
		}
	}
	metadata, err := json.Marshal(record)
	if err != nil {
		return Record{}, err
	}
	if err := writeOnce(filepath.Join(directory, metadataName), metadata); err != nil {
		return Record{}, err
	}
	if err := writeOnce(filepath.Join(directory, readyName), []byte(digest(metadata)+"\n")); err != nil {
		return Record{}, err
	}
	if err := syncDirectory(directory); err != nil {
		return Record{}, err
	}
	return record, nil
}

func Load(directory string) (Record, error) {
	if !filepath.IsAbs(directory) || secureParents(directory) != nil || secureDirectory(directory) != nil {
		return Record{}, ErrMaterial
	}
	metadata, err := readOwnedFile(filepath.Join(directory, metadataName), 1<<20)
	if err != nil {
		return Record{}, ErrMaterial
	}
	ready, err := readOwnedFile(filepath.Join(directory, readyName), 128)
	if err != nil || string(ready) != digest(metadata)+"\n" {
		return Record{}, ErrMaterial
	}
	var record Record
	if err := json.Unmarshal(metadata, &record, json.RejectUnknownMembers(true)); err != nil || record.SchemaVersion != 1 ||
		record.Config.validate() != nil ||
		len(record.Files) != len(expectedNames())+len(memberCANames)*boolInt(record.HasMemberCA()) ||
		record.ExpiresAt.Sub(record.IssuedAt) != time.Duration(record.Config.ValidityHours)*time.Hour {
		return Record{}, ErrMaterial
	}
	seen := make(map[string]bool, len(record.Files))
	for _, file := range record.Files {
		purpose, slot := classify(file.Name)
		if seen[file.Name] || file.Purpose != purpose || file.Slot != slot || purpose == "" ||
			file.MaxBytes <= 0 || file.MaxBytes > bootstrap.MaxSecretBytes {
			return Record{}, ErrMaterial
		}
		seen[file.Name] = true
		body, err := readOwnedFile(filepath.Join(directory, file.Name), file.MaxBytes)
		if err != nil || int64(len(body)) != file.MaxBytes || digest(body) != file.SHA256 {
			return Record{}, ErrMaterial
		}
		clear(body)
	}
	for _, name := range expectedNames() {
		if !seen[name] {
			return Record{}, ErrMaterial
		}
	}
	if seen[memberCANames[0]] != seen[memberCANames[1]] {
		return Record{}, ErrMaterial
	}
	entries, err := os.ReadDir(directory)
	if err != nil {
		return Record{}, ErrMaterial
	}
	allowed := map[string]bool{metadataName: true, readyName: true, journalName: true, journalTempName: true, journalLockName: true}
	for _, file := range record.Files {
		allowed[file.Name] = true
	}
	for _, entry := range entries {
		if !allowed[entry.Name()] {
			return Record{}, ErrMaterial
		}
		if entry.Name() == journalName {
			if _, err := readOwnedFile(filepath.Join(directory, entry.Name()), 1<<20); err != nil {
				return Record{}, ErrMaterial
			}
		} else if entry.Name() == journalTempName {
			if err := ownedRegular(filepath.Join(directory, entry.Name()), 0, 1<<20); err != nil {
				return Record{}, ErrMaterial
			}
		} else if entry.Name() == journalLockName {
			if err := ownedRegular(filepath.Join(directory, entry.Name()), 0, 0); err != nil {
				return Record{}, ErrMaterial
			}
		}
	}
	if len(entries) < len(record.Files)+2 {
		return Record{}, ErrMaterial
	}
	return record, nil
}

func GenerateLink(materialDirectory, homeMaterialDirectory, homeLinkDirectory, directory string, now time.Time) (LinkRecord, error) {
	material, err := Load(materialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	home, err := Load(homeMaterialDirectory)
	if err != nil || home.Config.Cell != natscell.LinkHome || material.Config.Environment != home.Config.Environment || material.Config.DeploymentID != home.Config.DeploymentID || now.IsZero() || now.Before(material.IssuedAt) || now.Before(home.IssuedAt) || !now.Before(material.ExpiresAt) || !now.Before(home.ExpiresAt) {
		return LinkRecord{}, ErrMaterial
	}
	isHome := material.Config.Cell == natscell.LinkHome
	if isHome && filepath.Clean(materialDirectory) != filepath.Clean(homeMaterialDirectory) || isHome && filepath.Clean(homeLinkDirectory) != filepath.Clean(directory) || !isHome && (nested(homeLinkDirectory, directory) || nested(directory, homeLinkDirectory)) {
		return LinkRecord{}, ErrMaterial
	}
	for _, source := range []string{materialDirectory, homeMaterialDirectory} {
		if !filepath.IsAbs(directory) || secureParents(directory) != nil || nested(source, directory) || nested(directory, source) {
			return LinkRecord{}, ErrMaterial
		}
	}
	if err := ValidateLive(materialDirectory, material); err != nil {
		return LinkRecord{}, err
	}
	if err := ValidateLive(homeMaterialDirectory, home); err != nil {
		return LinkRecord{}, err
	}
	sourceDigest, err := metadataDigest(materialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	homeDigest, err := metadataDigest(homeMaterialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	var homeLink LinkRecord
	homeLinkDigest := ""
	if !isHome {
		homeLink, err = GenerateLink(homeMaterialDirectory, homeMaterialDirectory, homeLinkDirectory, homeLinkDirectory, now)
		if err != nil {
			return LinkRecord{}, err
		}
		homeLinkDigest, err = metadataDigest(homeLinkDirectory)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	if _, err := os.Lstat(directory); err == nil {
		record, err := LoadLink(directory, now)
		if err != nil || record.SourceSHA256 != sourceDigest || record.HomeSHA256 != homeDigest || record.HomeLinkSHA256 != homeLinkDigest || !reflect.DeepEqual(record.Config, material.Config) || !reflect.DeepEqual(record.Public, material.Public) || record.HomeAccount != home.Public.CellAccountNKey || !isHome && record.Signer != homeLink.Signer {
			return LinkRecord{}, ErrMaterial
		}
		return record, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return LinkRecord{}, ErrMaterial
	}
	var homeClaim *jwt.AccountClaims
	if isHome {
		raw, err := readOwnedFile(filepath.Join(materialDirectory, "cell.jwt"), 64<<10)
		if err != nil {
			return LinkRecord{}, err
		}
		homeClaim, err = jwt.DecodeAccountClaims(string(raw))
		if err != nil || homeClaim.Subject != home.Public.CellAccountNKey || len(homeClaim.Imports) != 0 || len(homeClaim.Exports) != 0 || len(homeClaim.Mappings) != 0 || material.Config.LinkSigner != "" {
			return LinkRecord{}, ErrMaterial
		}
		if homeClaim.IssuedAt >= time.Now().Unix() {
			return LinkRecord{}, fmt.Errorf("%w: home cell claim was issued this second; retry after its issuance second", ErrMaterial)
		}
	}
	// Publish complete source bytes atomically; a crash before publication grants no authority.
	staging, err := os.MkdirTemp(filepath.Dir(directory), ".link-material-")
	if err != nil {
		return LinkRecord{}, err
	}
	defer os.RemoveAll(staging)
	files := map[string][]byte{}
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	record := LinkRecord{SchemaVersion: 1, Config: material.Config, Public: material.Public, IssuedAt: now.UTC(), ExpiresAt: minTime(material.ExpiresAt, home.ExpiresAt), SourceSHA256: sourceDigest, HomeSHA256: homeDigest, HomeLinkSHA256: homeLinkDigest, HomeAccount: home.Public.CellAccountNKey}
	var signer nkeys.KeyPair
	if isHome {
		signer, err = nkeys.CreateAccount()
		if err != nil {
			return LinkRecord{}, err
		}
		files["issuer-link.seed"], err = signer.Seed()
	} else {
		record.ExpiresAt = minTime(record.ExpiresAt, homeLink.ExpiresAt)
		seed, readErr := readOwnedFile(filepath.Join(homeLinkDirectory, "issuer-link.seed"), 4096)
		if readErr != nil {
			return LinkRecord{}, readErr
		}
		signer, err = nkeys.FromSeed(seed)
		clear(seed)
	}
	if err != nil {
		return LinkRecord{}, err
	}
	defer signer.Wipe()
	record.Signer, err = signer.PublicKey()
	if err != nil {
		return LinkRecord{}, err
	}
	if isHome {
		claim := homeClaim
		previousIssue := claim.IssuedAt
		natscell.ApplyLink(claim, record.Signer)
		seed, readErr := readOwnedFile(filepath.Join(materialDirectory, "issuer-operator.seed"), 4096)
		if readErr != nil {
			return LinkRecord{}, readErr
		}
		operator, decodeErr := nkeys.FromSeed(seed)
		clear(seed)
		if decodeErr != nil {
			return LinkRecord{}, decodeErr
		}
		claim.IssuedAt, claim.Expires = now.Unix(), record.ExpiresAt.Unix()
		encoded, encodeErr := claim.Encode(operator)
		operator.Wipe()
		if encodeErr != nil {
			return LinkRecord{}, encodeErr
		}
		if claim.IssuedAt <= previousIssue {
			return LinkRecord{}, ErrMaterial
		}
		files["link-cell.jwt"] = []byte(encoded)
	} else {
		files[bootstrap.LinkCredentialsFile], err = natscell.IssueLinkUser(signer, record.HomeAccount, material.Config.Cell, now, record.ExpiresAt)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	files["interregion-ca.pem"], err = readOwnedFile(filepath.Join(homeMaterialDirectory, "ca.pem"), 64<<10)
	if err != nil {
		return LinkRecord{}, err
	}
	ca, key, err := linkCA(files["interregion-ca.pem"], filepath.Join(homeMaterialDirectory, "issuer-ca.key"))
	if err != nil {
		return LinkRecord{}, err
	}
	for _, slot := range material.Config.Slots {
		template := &x509.Certificate{Subject: pkix.Name{CommonName: material.Config.Cell + " " + slot.Name + " link"}, NotBefore: now.Add(-time.Minute), NotAfter: record.ExpiresAt, KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}, DNSNames: []string{InterRegionLeafName(material.Config.Cell)}}
		if isHome {
			template.ExtKeyUsage = append(template.ExtKeyUsage, x509.ExtKeyUsageServerAuth)
			template.DNSNames = []string{natscell.LinkServerName}
		}
		certName, keyName := bootstrap.InterRegionTLSFiles(slot.Name)
		files[certName], files[keyName], _, _, err = interRegionCertificate(template, ca, key)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	for _, name := range slices.Sorted(maps.Keys(files)) {
		purpose, slot := linkPurpose(name)
		body := files[name]
		if len(body) == 0 || len(body) > maxInterRegionFile {
			return LinkRecord{}, ErrMaterial
		}
		record.Files = append(record.Files, File{Name: name, Purpose: purpose, Slot: slot, SHA256: digest(body), MaxBytes: int64(len(body))})
		if err := writeOnce(filepath.Join(staging, name), body); err != nil {
			return LinkRecord{}, err
		}
	}
	wire, err := json.Marshal(record)
	if err != nil {
		return LinkRecord{}, err
	}
	if err := writeOnce(filepath.Join(staging, metadataName), wire); err != nil {
		return LinkRecord{}, err
	}
	if err := writeOnce(filepath.Join(staging, readyName), []byte(digest(wire)+"\n")); err != nil {
		return LinkRecord{}, err
	}
	if err := syncDirectory(staging); err != nil {
		return LinkRecord{}, err
	}
	if err := unix.Renameat2(unix.AT_FDCWD, staging, unix.AT_FDCWD, directory, unix.RENAME_NOREPLACE); err != nil && !errors.Is(err, unix.EEXIST) {
		return LinkRecord{}, err
	}
	if err := syncDirectory(filepath.Dir(directory)); err != nil {
		return LinkRecord{}, err
	}
	return GenerateLink(materialDirectory, homeMaterialDirectory, homeLinkDirectory, directory, now)
}

func automaticControllerConfig(manifest bootstrap.Manifest, record bootstrapmaterial.Record, signerWire []byte, now time.Time) (bootstrap.Manifest, error) {
	signers, err := automaticStartupSigners(signerWire)
	if err != nil {
		return bootstrap.Manifest{}, err
	}
	config, err := ControllerConfigFromRecord(manifest, record, signers[0], now)
	if err != nil {
		return bootstrap.Manifest{}, err
	}
	config.Controller.TrustedSigners = signers
	return automaticRenderedControllerConfig(manifest, config)
}

func automaticRenderedControllerConfig(manifest bootstrap.Manifest, config Config) (bootstrap.Manifest, error) {
	wire, err := protocol.EncodeJSON(config)
	if err != nil || len(wire) > bootstrap.MaxControllerConfigBytes {
		return bootstrap.Manifest{}, errors.New("derived controller configuration exceeds its size bound")
	}
	manifest.ControllerConfig = wire
	manifest.ControllerConfigSHA256 = controllerSHA256(wire)
	if _, err := ValidateSignedControllerConfig(manifest, ""); err != nil {
		return bootstrap.Manifest{}, fmt.Errorf("validate derived controller configuration: %w", err)
	}
	return manifest, nil
}

func ControllerConfigFromRecord(manifest bootstrap.Manifest, record bootstrapmaterial.Record,
	grant TrustedSignerConfig, now time.Time,
) (Config, error) {
	publicKey, keyErr := base64.StdEncoding.Strict().DecodeString(record.Public.ControllerResponsePublicKey)
	prefix, prefixErr := netip.ParsePrefix(record.Config.SubnetCIDR)
	if record.SchemaVersion != 1 || record.Config.DeploymentID != manifest.DeploymentID ||
		record.Config.ClusterID != manifest.ClusterID || record.Config.Environment != manifest.Environment ||
		record.Config.Cell != strings.ToLower(string(manifest.Cell)) || record.Config.Region != manifest.OCIRegion ||
		len(record.Config.Slots) != len(manifest.ControllerSlots) || len(record.Config.Slots) != 3 ||
		!now.Before(record.ExpiresAt) || record.IssuedAt.IsZero() ||
		keyErr != nil || len(publicKey) != ed25519.PublicKeySize ||
		prefixErr != nil || !prefix.Addr().Is4() || !prefix.Addr().IsPrivate() || prefix.Masked() != prefix {
		return Config{}, errors.New("reviewed material record does not match the candidate deployment")
	}
	secretFiles := make(map[string]bootstrapmaterial.File, len(record.Files))
	for _, file := range record.Files {
		if file.Name == "" || file.Name != filepath.Base(file.Name) || file.SHA256 == "" ||
			file.MaxBytes <= 0 || len(secretFiles) >= 64 {
			return Config{}, errors.New("reviewed material inventory is invalid")
		}
		if _, exists := secretFiles[file.Name]; exists {
			return Config{}, errors.New("reviewed material inventory repeats an output")
		}
		secretFiles[file.Name] = file
	}
	for _, reference := range manifest.Secrets {
		file, exists := secretFiles[reference.TargetFile]
		if !exists || file.Purpose != reference.Purpose || file.Slot != reference.Slot ||
			file.SHA256 != reference.SHA256 || file.MaxBytes != reference.MaxBytes {
			return Config{}, fmt.Errorf("signed material reference %s differs from reviewed source", reference.TargetFile)
		}
	}
	// Material generated before the member CA existed renders without it.
	for _, name := range []string{"terrabase-member-ca.pem", "terrabase-member-ca.key"} {
		if record.HasMemberCA() && !slices.ContainsFunc(manifest.Secrets, func(reference bootstrap.SecretReference) bool {
			return reference.TargetFile == name && reference.Purpose == bootstrap.SecretHostIssuer
		}) {
			return Config{}, fmt.Errorf("candidate manifest does not reference the TerraBase member CA secret %s", name)
		}
	}
	addresses := make(map[string]string, len(record.Config.Slots))
	for index, slot := range record.Config.Slots {
		address, err := netip.ParseAddr(slot.PrivateIP)
		if err != nil || slot.Name != manifest.ControllerSlots[index] || !address.Is4() || !prefix.Contains(address) ||
			address == prefix.Addr() || address == prefix.Addr().Next() || address.String() != slot.PrivateIP {
			return Config{}, errors.New("reviewed controller slot address or order differs from signed candidate")
		}
		if slices.ContainsFunc(record.Config.Slots[:index], func(prior bootstrapmaterial.Slot) bool {
			return prior.PrivateIP == slot.PrivateIP
		}) {
			return Config{}, errors.New("reviewed controller private addresses repeat")
		}
		addresses[slot.Name] = slot.PrivateIP
	}
	host, exists := addresses[manifest.Slot]
	if !exists {
		return Config{}, errors.New("candidate slot is absent from reviewed controller inventory")
	}
	path := func(name string) string { return filepath.Join(bootstrapstart.MaterialDirectory, name) }
	tls := natscell.TLSFiles{CAFile: path("ca.pem"), CertFile: path(manifest.Slot + "-tls-cert.pem"),
		KeyFile: path(manifest.Slot + "-tls-key.pem")}
	routes := make([]string, 0, len(record.Config.Slots)-1)
	for _, slot := range record.Config.Slots {
		if slot.Name != manifest.Slot {
			routes = append(routes, "nats-route://"+slot.PrivateIP+":6222")
		}
	}
	cfg := Config{Version: ConfigVersion,
		NATS: natscell.Config{Cell: record.Config.Cell, Instance: manifest.Slot, Replicas: len(record.Config.Slots),
			ClientRole: "controller", URL: "tls://" + host + ":4222", CredentialsFile: path(manifest.Slot + ".creds"),
			TLS: tls, Embedded: &natscell.Embedded{Host: host, Port: 4222, RouteHost: host, RoutePort: 6222,
				Routes: routes, StoreDir: "/var/lib/terrascale-orchestrator-controller/nats", StoreMaxBytes: 4 << 30,
				TLS: tls, RouteTLS: tls, RouteUser: "ts-route", RoutePasswordFile: path("route-password"),
				OperatorJWTFile: path("operator.jwt"), SystemJWTFile: path("system.jwt"),
				CellJWTFile: path("cell.jwt"), SystemCredentialsFile: path("system.creds"),
				TicketPublicKeyFile: path("ticket.pub"), BrokerIDs: slices.Clone(manifest.ControllerSlots)}},
		Controller: ControllerConfig{CandidateID: entityid.Derive("controller", manifest.DeploymentID, string(manifest.Cell), manifest.Slot),
			ArtifactStoreMaxBytes: 512 << 20,
			ResponseKeyFile:       path(manifest.Slot + "-response.key"), BrokerTicketKeyFile: path("ticket.key"),
			HostNATSIssuerSeedFile:      path("host-nats-issuer.seed"),
			HostTLSIssuerKeyFile:        path("host-tls-issuer-key.pem"),
			HostTLSIssuerCertFile:       path("host-tls-issuer-cert.pem"),
			HostEnrollmentListenAddress: host + ":8443",
			OciRegionIntentFile:         "/etc/terrascale-orchestrator/oci-region-intent.json",
			OciRegionConfig:             "/etc/terrascale-orchestrator/oci-region.json",
			PlacementConfig:             "/etc/terrascale-orchestrator/placement.json",
			TrustedSigners:              []TrustedSignerConfig{grant}},
	}
	if record.HasMemberCA() {
		cfg.Controller.TerraBaseCACertFile = path("terrabase-member-ca.pem")
		cfg.Controller.TerraBaseCAKeyFile = path("terrabase-member-ca.key")
	}
	return cfg, nil
}

func automaticControllerConfigWithLink(manifest bootstrap.Manifest, record bootstrapmaterial.Record,
	link bootstrapmaterial.LinkRecord, signerWire []byte, now time.Time,
) (bootstrap.Manifest, error) {
	if link.SchemaVersion != 1 || !reflect.DeepEqual(link.Config, record.Config) || link.Public != record.Public ||
		link.IssuedAt.IsZero() || now.Before(link.IssuedAt) || !now.Before(link.ExpiresAt) {
		return bootstrap.Manifest{}, errors.New("startup Link material differs from the regional source")
	}
	signers, err := automaticStartupSigners(signerWire)
	if err != nil {
		return bootstrap.Manifest{}, err
	}
	record.Files = slices.Clone(record.Files)
	for _, file := range link.Files {
		if file.Purpose == "owner-only" {
			continue
		}
		name := file.Name
		if name == "link-cell.jwt" {
			file.Name = "cell.jwt"
		}
		index := slices.IndexFunc(record.Files, func(existing bootstrapmaterial.File) bool {
			return existing.Name == file.Name
		})
		if index >= 0 {
			if name != "link-cell.jwt" {
				return bootstrap.Manifest{}, errors.New("startup Link inventory replaces regional source material")
			}
			record.Files[index] = file
		} else {
			record.Files = append(record.Files, file)
		}
	}
	config, err := ControllerConfigFromRecord(manifest, record, signers[0], now)
	if err != nil {
		return bootstrap.Manifest{}, err
	}
	block, err := bootstrapmaterial.RenderLink(link, manifest.Slot, bootstrapstart.MaterialDirectory)
	if err != nil {
		return bootstrap.Manifest{}, err
	}
	for _, path := range block.Files() {
		if !slices.ContainsFunc(manifest.Secrets, func(ref bootstrap.SecretReference) bool {
			return ref.TargetFile == filepath.Base(path) && ref.Purpose == bootstrap.SecretInterRegion &&
				(ref.Slot == "" || ref.Slot == manifest.Slot)
		}) {
			return bootstrap.Manifest{}, errors.New("startup Link credential is absent from signed material")
		}
	}
	config.NATS.Embedded.Link = &block
	config.Controller.TrustedSigners = signers
	return automaticRenderedControllerConfig(manifest, config)
}

func LoadConfig(path string) (Config, error) {
	if path == "" {
		return Config{}, errors.New("--config is required")
	}
	info, err := os.Stat(path)
	if err != nil {
		return Config{}, fmt.Errorf("stat config: %w", err)
	}
	if info.Size() > maxConfigBytes {
		return Config{}, errors.New("config is too large")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read config: %w", err)
	}
	cfg, err := decodeConfig(data)
	if err != nil {
		return Config{}, fmt.Errorf("parse config: %w", err)
	}
	if err := cfg.Observability.Validate(); err != nil {
		return Config{}, fmt.Errorf("observability config: %w", err)
	}
	if api := cfg.Controller.MachinesAPI; api != nil {
		if err := api.Validate(); err != nil {
			return Config{}, err
		}
	}
	return cfg, nil
}

func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil
}

// signedWire returns the exact bytes the config was read from, or its
// canonical encoding when code built it.
func (c Config) signedWire() ([]byte, error) {
	if c.wire != nil {
		return c.wire, nil
	}
	if c.Version != 0 && c.Version != ConfigVersion {
		return nil, fmt.Errorf("unsupported config version %d; want %d", c.Version, ConfigVersion)
	}
	c.Version = ConfigVersion
	return protocol.EncodeJSON(c)
}

