func (s *Sampler) Sample(terrabase map[string]memberstatus.Load) Report {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.config.Now()
	report := Report{SchemaVersion: SchemaVersion}
	memTotal := uint64(0)
	if view, err := s.config.ReadSystem(s.config.Filesystems); err == nil {
		memTotal = view.MemTotalBytes
		if view.CPUCount > 0 && view.CPUCount <= MaxCPUCores {
			report.Host.CPUCores = view.CPUCount
		}
		if view.MemTotalBytes <= MaxMemoryBytes {
			report.Host.MemoryBytes = view.MemTotalBytes
		}
		busy := view.CPUSeconds.Busy()
		total := busy + view.CPUSeconds.Idle + view.CPUSeconds.IOWait
		if s.hostSeen && total > s.host.total && busy >= s.host.usage {
			report.Host.CPU = ratio(busy-s.host.usage, total-s.host.total)
		}
		s.host, s.hostSeen = cpuPoint{usage: busy, total: total, at: now}, true
		if view.MemTotalBytes > 0 && view.MemAvailBytes <= view.MemTotalBytes {
			report.Host.Memory = ratio(float64(view.MemTotalBytes-view.MemAvailBytes), float64(view.MemTotalBytes))
		}
		if finiteWithin(view.Load1, MaxLoad1) {
			load := view.Load1
			report.Host.Load1 = &load
		}
		if rx, tx := view.NetRxBytes, view.NetTxBytes; rx > 0 && tx > 0 {
			// A counter that went backwards means the interface reset, so
			// that interval has no valid rate.
			if elapsed := now.Sub(s.net.at).Seconds(); s.net.seen && elapsed > 0 && rx >= s.net.rx && tx >= s.net.tx {
				rxBps := float64(rx-s.net.rx) / elapsed
				txBps := float64(tx-s.net.tx) / elapsed
				if finiteWithin(rxBps, MaxNetworkBps) && finiteWithin(txBps, MaxNetworkBps) {
					report.Host.NetworkRxBps, report.Host.NetworkTxBps = &rxBps, &txBps
				}
			}
			s.net = netPoint{rx: rx, tx: tx, at: now, seen: true}
		}
		seen := make(map[string]bool)
		for _, filesystem := range view.Filesystems {
			if len(report.Host.Filesystems) == MaxFilesystems {
				report.Host.FilesystemsIncomplete = true
				break
			}
			if !validFilesystem(filesystem) || seen[filesystem.Role] {
				report.Host.FilesystemsIncomplete = true
				continue
			}
			seen[filesystem.Role] = true
			report.Host.Filesystems = append(report.Host.Filesystems, filesystem)
			used := ratio(float64(filesystem.SizeBytes-filesystem.AvailBytes), float64(filesystem.SizeBytes))
			if report.Host.Disk == nil || *used > *report.Host.Disk {
				report.Host.Disk = used
			}
		}
	} else {
		report.Host.FilesystemsIncomplete = true
	}
	present := make(map[string]struct{}, len(s.config.Roles))
	for _, role := range s.config.Roles {
		if len(report.Roles) == MaxRoles {
			break
		}
		usage, seen := s.sampleCgroup(role, now, memTotal)
		if seen {
			present[role] = struct{}{}
		}
		if load, ok := terrabase[role]; ok && load.Validate() == nil {
			usage.TerraBase = &load
		}
		if usage.CPUCores != nil || usage.MemoryBytes != nil || usage.TerraBase != nil {
			report.Roles = append(report.Roles, usage)
		}
	}
	// A role whose group vanished (stopped workload) restarts its CPU
	// baseline when it comes back, so a restart never reads as a burst.
	s.forgetCgroups(present)
	return report
}

func (t *hostTelemetry) current() bool {
	snapshot := t.fencer.Current()
	if !snapshot.CanMutate() {
		t.load.Reset()
		clear(t.managedRequests)
		clear(t.usagePoints)
		t.epoch = 0
		return false
	}
	if t.epoch != snapshot.Epoch {
		t.load.Reset()
		clear(t.managedRequests)
		clear(t.usagePoints)
		t.epoch = snapshot.Epoch
	}
	return true
}

func (t *hostTelemetry) record(origin hostload.Origin, report hostload.Report) error {
	t.mu.Lock()
	defer t.mu.Unlock()
	if !t.current() {
		return authority.ErrFenced
	}
	return t.load.Record(origin, report)
}

func (t *hostTelemetry) archiveBatch(at time.Time) observability.HostMetricBatch {
	t.mu.Lock()
	defer t.mu.Unlock()
	if !t.current() {
		return observability.HostMetricBatch{}
	}
	samples := hostLoadSamples(t.load)
	samples = slices.DeleteFunc(samples, func(sample observability.Sample) bool {
		return !observability.IsHostMetric(sample.Metric)
	})
	// Keep the same series first when a region exceeds archive capacity.
	slices.SortFunc(samples, func(a, b observability.Sample) int {
		if order := strings.Compare(a.Labels[0].Value, b.Labels[0].Value); order != 0 {
			return order
		}
		if order := cmp.Compare(len(a.Labels), len(b.Labels)); order != 0 {
			return order
		}
		if len(a.Labels) >= 2 {
			if order := strings.Compare(a.Labels[1].Value, b.Labels[1].Value); order != 0 {
				return order
			}
		}
		return strings.Compare(a.Metric, b.Metric)
	})
	return observability.HostMetricBatch{Version: observability.HostMetricBatchVersion, At: at.UTC().Truncate(observability.HostMetricInterval),
		Epoch: t.epoch, Samples: samples}
}

func OpenHostMetricStream(ctx context.Context, js jetstream.JetStream, cell string, replicas int) (*HostMetricStream, error) {
	if js == nil {
		return nil, errors.New("host metric stream requires JetStream")
	}
	if replicas < 1 || replicas > 5 {
		return nil, errors.New("host metric stream replica count is out of range")
	}
	subject, err := protocol.ObservabilitySubject(cell, "host-metrics")
	if err != nil {
		return nil, err
	}
	stream, err := js.CreateStream(ctx, jetstream.StreamConfig{
		Name:        HostMetricStreamName,
		Description: "Regional host metric history",
		Subjects:    []string{subject + "." + strings.ToLower(rand.Text())},
		Storage:     jetstream.FileStorage,
		Replicas:    replicas,
		Retention:   jetstream.LimitsPolicy,
		Discard:     jetstream.DiscardNew,
		MaxAge:      HistoryRetention,
		MaxBytes:    HostMetricStreamBytes,
		MaxMsgs:     -1,
		MaxMsgSize:  HostMetricBatchBytes + hostMetricHeaderBytes,
	})
	if errors.Is(err, jetstream.ErrStreamNameAlreadyInUse) {
		stream, err = js.Stream(ctx, HostMetricStreamName)
	}
	if err != nil {
		return nil, fmt.Errorf("open host metric stream: %w", err)
	}
	info := stream.CachedInfo()
	if len(info.Config.Subjects) != 1 || !strings.HasPrefix(info.Config.Subjects[0], subject+".") ||
		protocol.ValidateSubjectToken(strings.TrimPrefix(info.Config.Subjects[0], subject+".")) != nil {
		return nil, errors.New("host metric stream lacks a v1 generation subject; delete and recreate it")
	}
	config := info.Config
	if config.Storage != jetstream.FileStorage || config.Replicas != replicas || config.Retention != jetstream.LimitsPolicy ||
		config.Discard != jetstream.DiscardNew || config.MaxAge != HistoryRetention || config.MaxBytes != HostMetricStreamBytes ||
		config.MaxMsgs != -1 || config.MaxMsgSize != HostMetricBatchBytes+hostMetricHeaderBytes || config.NoAck ||
		config.SubjectTransform != nil || config.Mirror != nil || len(config.Sources) != 0 || config.RePublish != nil {
		return nil, errors.New("host metric stream contract differs from v1; delete and recreate it")
	}
	// The server rejects old-generation writes even when recreation races an in-flight request.
	return &HostMetricStream{stream: stream, createdAt: info.Created, js: js, subject: info.Config.Subjects[0]}, nil
}

func (stream *HostMetricStream) Publish(ctx context.Context, batch HostMetricBatch) (bool, error) {
	if err := ctx.Err(); err != nil {
		return false, err
	}
	batch.At = batch.At.UTC().Truncate(HostMetricInterval)
	data, err := encodeHostMetricBatch(batch)
	if err != nil {
		return false, err
	}
	for range hostMetricPublishAttempts {
		info, err := stream.info(ctx)
		if err != nil {
			return false, err
		}
		lastSeq := info.State.LastSeq
		if info.State.Msgs > 0 {
			message, err := stream.message(ctx, lastSeq)
			if errors.Is(err, jetstream.ErrMsgNotFound) {
				continue // Retention may have expired the message after Info.
			}
			if err != nil {
				return false, err
			}
			if message.Subject != stream.subject {
				return false, errors.New("host metric publication crossed stream generation")
			}
			last, err := decodeHostMetricBatch(message.Data)
			if err != nil {
				return false, fmt.Errorf("read latest host metric batch: %w", err)
			}
			if !batch.At.After(last.At) {
				return bytes.Equal(message.Data, data), nil
			}
		}
		_, err = stream.js.Publish(ctx, stream.subject, data, jetstream.WithExpectLastSequence(lastSeq))
		if err == nil {
			return true, nil
		}
		var apiErr *jetstream.APIError
		if !errors.As(err, &apiErr) || (apiErr.ErrorCode != jetstream.JSErrCodeStreamWrongLastSequence &&
			apiErr.ErrorCode != jetstream.JSErrCodeStreamWrongLastSequenceConstant) {
			return false, err
		}
	}
	if err := ctx.Err(); err != nil {
		return false, err
	}
	return false, errors.New("host metric publish contention exceeded retry bound")
}

func (stream *HostMetricStream) Tail(ctx context.Context, history *History) error {
	stream.caughtUp.Store(false)
	defer stream.caughtUp.Store(false)
	if history == nil {
		return errors.New("host metric tail requires history")
	}
	var next uint64
	backoff := time.Second
	for ctx.Err() == nil {
		err := stream.tailHostMetricsOnce(ctx, history, &next)
		if ctx.Err() != nil {
			return ctx.Err()
		}
		slog.DebugContext(ctx, "host metric stream tail restarting", ComponentKey, "observability", "error", err)
		timer := time.NewTimer(backoff)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
		backoff = min(backoff*2, 30*time.Second)
	}
	return ctx.Err()
}

func (stream *HostMetricStream) tailHostMetricsOnce(ctx context.Context, history *History, next *uint64) error {
	stream.caughtUp.Store(false)
	defer stream.caughtUp.Store(false)
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	connection := stream.js.Conn()
	statuses := connection.StatusChanged(nats.RECONNECTING, nats.DISCONNECTED, nats.CLOSED)
	defer connection.RemoveStatusListener(statuses)
	done := make(chan struct{})
	go func() {
		defer close(done)
		ticker := time.NewTicker(hostMetricReplayWait)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-statuses:
				stream.caughtUp.Store(false)
				cancel()
				return
			case <-ticker.C:
				checkCtx, cancelCheck := context.WithTimeout(ctx, hostMetricReplayWait)
				_, err := stream.info(checkCtx)
				cancelCheck()
				if err != nil {
					stream.caughtUp.Store(false)
					cancel()
					return
				}
			}
		}
	}()
	defer func() { cancel(); <-done }()
	info, err := stream.info(ctx)
	if err != nil {
		return err
	}
	caughtUp := info.State.LastSeq
	config := jetstream.OrderedConsumerConfig{DeliverPolicy: jetstream.DeliverAllPolicy, FilterSubjects: []string{stream.subject}}
	if *next != 0 {
		config.DeliverPolicy, config.OptStartSeq = jetstream.DeliverByStartSequencePolicy, *next
	}
	consumer, err := stream.stream.OrderedConsumer(ctx, config)
	if err != nil {
		return err
	}
	messages, err := consumer.Messages()
	if err != nil {
		return err
	}
	defer messages.Stop()
	stop := context.AfterFunc(ctx, messages.Stop)
	defer stop()
	if ctx.Err() == nil && (info.State.Msgs == 0 || *next > caughtUp) {
		stream.caughtUp.Store(true)
	}
	type replayRecord struct {
		sequence uint64
		data     []byte
	}
	// Bound buffered payloads and validate one generation per chunk, not per minute.
	pending := make([]replayRecord, 0, hostMetricReplayChunk)
	readNext := *next
	flush := func() (*jetstream.StreamInfo, error) {
		info, err := stream.info(ctx)
		if err != nil {
			return nil, err
		}
		for _, record := range pending {
			if err := ctx.Err(); err != nil {
				return nil, err
			}
			if batch, err := decodeHostMetricBatch(record.data); err == nil {
				if batch.Incomplete {
					stream.archiveIncomplete.Store(true)
				}
				history.Append(batch.At, batch.Samples)
			} else {
				stream.rejectReplayBatch(record.sequence)
			}
			*next = record.sequence + 1
		}
		clear(pending)
		pending = pending[:0]
		if ctx.Err() == nil && *next > caughtUp {
			stream.caughtUp.Store(true)
		}
		return info, nil
	}
	for {
		nextCtx, cancelNext := context.WithTimeout(ctx, hostMetricReplayWait)
		message, err := messages.Next(jetstream.NextContext(nextCtx))
		cancelNext()
		if errors.Is(err, context.DeadlineExceeded) && ctx.Err() == nil {
			info, err := flush()
			if err != nil {
				return err
			}
			// Retention may remove the replay target before it can be delivered.
			if ctx.Err() == nil && (info.State.Msgs == 0 || *next > info.State.LastSeq) {
				stream.caughtUp.Store(true)
			}
			continue // NextContext deadlines leave the iterator usable.
		}
		if err != nil {
			return err
		}
		if message.Subject() != stream.subject {
			return errors.New("host metric replay crossed stream generation")
		}
		metadata, err := message.Metadata()
		if err != nil {
			return err
		}
		sequence := metadata.Sequence.Stream
		if sequence < readNext {
			continue
		}
		pending = append(pending, replayRecord{sequence: sequence, data: message.Data()})
		readNext = sequence + 1
		if len(pending) == hostMetricReplayChunk || sequence >= caughtUp {
			if _, err := flush(); err != nil {
				return err
			}
		}
	}
}

func CollectResources(node Node, history observability.HistorySource, now time.Time) *ResourceView {
	resources := new(ResourceView)
	received := resources.latest(history, observability.HistHostReceivedAt, node.Name, now)
	if received == nil || received.Value <= 0 || received.Value > float64(now.UnixMilli()) {
		return resources
	}
	resources.batchAt = received.ObservedAt
	resources.ObservedAt = time.UnixMilli(int64(received.Value)).UTC()
	if incomplete := resources.latest(history, observability.HistHostFSIncomplete, node.Name, now); incomplete != nil && incomplete.Value == 1 {
		resources.Incomplete = true
	}
	resources.CPUCores = resources.latest(history, observability.HistHostCPUCores, node.Name, now)
	resources.CPU = resources.latest(history, observability.HistHostCPUUtilization, node.Name, now)
	resources.MemoryBytes = resources.latest(history, observability.HistHostMemoryTotal, node.Name, now)
	resources.Memory = resources.latest(history, observability.HistHostMemoryRatio, node.Name, now)
	resources.Disk = resources.latest(history, observability.HistHostDiskRatio, node.Name, now)
	if resources.MemoryBytes != nil && resources.Memory != nil && resources.MemoryBytes.ObservedAt.Equal(resources.Memory.ObservedAt) {
		resources.MemoryUsedBytes = &Reading{Value: resources.MemoryBytes.Value * resources.Memory.Value, ObservedAt: resources.Memory.ObservedAt}
	}
	resources.filesystems(history, node.Name, now)
	return resources
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func (history *History) Append(at time.Time, samples []Sample) {
	millis := at.UnixMilli()
	history.mu.Lock()
	defer history.mu.Unlock()
	minute := millis / time.Minute.Milliseconds()
	history.newestMinute = max(history.newestMinute, minute)
	oldestMinute := history.newestMinute - int64(rawRetention/time.Minute)
	for at := range history.dropMinutes {
		if at < oldestMinute {
			delete(history.dropMinutes, at)
		}
	}
	// Prune first, so series that stopped reporting free their slots.
	stale := millis - history.config.StaleAfter.Milliseconds()
	for key, current := range history.series {
		if current.last < stale {
			delete(history.series, key)
		}
	}
	for _, sample := range samples {
		if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Metric == "" {
			continue
		}
		labels := sortedLabels(sample.Labels)
		key := seriesKey(sample.Metric, labels)
		current, ok := history.series[key]
		if !ok {
			if len(history.series) >= history.config.MaxSeries {
				history.dropped++
				if minute >= oldestMinute {
					history.dropMinutes[minute] = true
				}
				historyDropped.Inc()
				continue
			}
			current = history.newSeries(sample.Metric, labels, sample.Counter)
			history.series[key] = current
		}
		if millis < current.last {
			continue
		}
		// A counter's growth since its previous raw sample, reset-correct:
		// a decrease is a restart that counted again from zero.
		increase, counted := 0.0, false
		if current.counter && current.sampled {
			increase, counted = sample.Value-current.lastValue, true
			if increase < 0 {
				increase = sample.Value
			}
		}
		current.last, current.lastValue, current.sampled = millis, sample.Value, true
		for _, name := range []string{TierRaw, Tier1m, Tier5m, Tier1h} {
			current.tiers[name].add(millis, sample.Value, increase, counted)
		}
		historySamples.Inc()
	}
}

func (history *History) Range(query HistoryQuery) HistoryResult {
	if query.End.IsZero() {
		query.End = time.Now()
	}
	if query.Start.IsZero() {
		query.Start = query.End.Add(-time.Hour)
	}
	chosen := query.Tier
	if chosen == "" {
		chosen = TierFor(query.Start, time.Now())
	}
	if query.MaxSeries <= 0 {
		query.MaxSeries = 64
	}
	query.MaxSeries = min(query.MaxSeries, 512)
	start, end := query.Start.UnixMilli(), query.End.UnixMilli()
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	history.mu.RLock()
	defer history.mu.RUnlock()
	result := HistoryResult{RetentionStart: time.UnixMilli(cutoff).UTC(),
		IntervalSeconds: history.config.Interval.Seconds(), DroppedSeries: history.dropped}
	for minute := range history.dropMinutes {
		if minute >= start/time.Minute.Milliseconds() && minute <= end/time.Minute.Milliseconds() {
			result.Incomplete = true
			break
		}
	}
	keys := slices.Sorted(maps.Keys(history.series))
	for _, key := range keys {
		current := history.series[key]
		if current.metric != query.Metric || !labelsMatch(current.labels, query.Labels) {
			continue
		}
		if query.Rate && !current.counter {
			result.UnsupportedReason = "rate_requires_counter"
			continue
		}
		tierName := chosen
		if query.Tier == "" {
			tierName = current.coveringTier(chosen, start, end, cutoff)
		}
		t, ok := current.tiers[tierName]
		if !ok {
			continue
		}
		out := HistorySeries{Metric: current.metric, Tier: tierName, Labels: labelMap(current.labels)}
		var previous *bucket
		var lastAt int64
		expected := max(history.config.Interval, t.step).Milliseconds()
		for _, b := range t.buckets() {
			if b.lastAt() < cutoff {
				continue
			}
			if b.Start > end {
				break
			}
			if b.Start < start-t.step.Milliseconds() {
				copied := b
				previous = &copied
				continue
			}
			if lastAt != 0 && b.lastAt()-lastAt > 2*expected {
				out.Gaps = true
			}
			lastAt = b.lastAt()
			if query.Rate {
				if previous != nil && b.lastAt() > previous.lastAt() {
					delta := b.Last - previous.Last
					if delta < 0 { // counter reset
						delta = b.Last
					}
					if b.Increased {
						// Growth accumulated per raw sample also counts a
						// reset and recovery inside the bucket.
						delta = b.Increase
					}
					rate := delta / (float64(b.lastAt()-previous.lastAt()) / 1000)
					out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: rate,
						Min: rate, Max: rate})
				}
				copied := b
				previous = &copied
				continue
			}
			value := b.Sum / float64(b.Count)
			if current.counter {
				value = b.Last
			}
			out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: value,
				Min: b.Min, Max: b.Max, Samples: b.Count})
		}
		out.LastObservedAt = time.UnixMilli(lastAt).UTC()
		out.Stale = end-lastAt > 2*expected
		// A stored series without points in the range does not take one
		// of the result's slots.
		if len(out.Points) == 0 {
			continue
		}
		if len(result.Series) == query.MaxSeries {
			result.Truncated = true
			break
		}
		result.Series = append(result.Series, out)
	}
	return result
}

